@GameTestHolder("lawsjustice") @PrefixGameTestTemplate(false)
public final class FinanceGameTests {
 private FinanceGameTests(){}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void fineRequiresAnActualHearingAndAtomicPersistedVerdict(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID id=f.court.file();f.court.open(f.court.judge);var req=f.court.verdict(id);req.addProperty("amount","20");f.court.act(f.court.judge,"court_fine",req);h.assertTrue(f.finance().charges().isEmpty(),"Fine bypassed a hearing");f.court.hear(id);req=f.court.verdict(id);req.addProperty("amount","20");f.court.act(f.court.judge,"court_fine",req);var restored=JusticeData.readState(f.court.base.directory.resolve("laws_justice.dat"));h.assertTrue(restored.court().cases().get(id).status().equals("FINED")&&restored.finance().charges().size()==1&&restored.ledger().active().isEmpty(),"Fine and verdict did not persist together or invented custody");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void actualPlayerPaymentSavesOneWalletDebitAndOneReceipt(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var p=f.court.accused;long before=f.balance(p),amount=f.finance().charges().get(charge).amount();UUID id=MoneySettlement.pay(p,charge);var payment=f.finance().payments().get(id);h.assertTrue(payment.status().equals("PAID"),"Actual payment did not settle: "+MoneySettlement.error(p.server,id));h.assertTrue(f.balance(p)==before-amount&&PaymentReceipts.live(p,payment)&&PaymentReceipts.durable(p.server,payment),"Player debit and receipt were not saved together");for(int i=0;i<4;i++){MoneySettlement.progress(p.server,id,true);JusticeFixture.rejected(h,()->MoneySettlement.pay(p,charge));}h.assertTrue(f.balance(p)==before-amount&&f.finance().payments().size()==1&&f.finance().escrow(payment.currency())==amount,"Replaying a settled payment debited or funded twice");System.out.println("JUSTICE_FINANCE_PAYMENT_PASSED integration="+Boolean.getBoolean("justice.integration"));}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void insufficientBalanceCreatesNoDebitNoPaymentAndNoNewSentence(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var p=f.court.accused;if(JusticeWallet.currentCurrency().equals("CHRONICLES"))JusticeWallet.debit(p,"CHRONICLES",f.balance(p));else p.getInventory().clearContent();JusticeFixture.rejected(h,()->MoneySettlement.pay(p,charge));h.assertTrue(f.finance().payments().isEmpty()&&f.court.base.data.ledger().active().isEmpty()&&f.finance().charges().get(charge).status().equals("DUE"),"Poverty created a new penalty or a partial debit");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void onlyTheAccusedPaysAFineAndClientCannotOverridePrice(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();JusticeFixture.rejected(h,()->MoneySettlement.pay(f.court.stranger,charge));f.open(f.court.accused);long before=f.balance(f.court.accused);var req=f.mutation(f.court.accused);req.addProperty("charge",charge.toString());req.addProperty("amount",1);f.act(f.court.accused,"finance_pay",req);h.assertTrue(f.balance(f.court.accused)==before&&f.finance().payments().isEmpty(),"Forged client price changed the server charge");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void aFriendPaysBailForAnOfflinePrisonerAndQueuesTheRelease(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.bail();var target=f.court.accused;f.court.base.actors.disconnect(target);var payer=f.court.stranger;long before=f.balance(payer);UUID id=MoneySettlement.pay(payer,charge);var paid=f.finance().payments().get(id);h.assertTrue(paid.status().equals("PAID"),"Friend bail payment failed: "+MoneySettlement.error(payer.server,id));h.assertTrue(f.balance(payer)==before-paid.amount()&&!f.court.base.data.ledger().active().containsKey(target.getUUID()),"Bail charged the wrong wallet or left exact custody active");var restored=JusticeData.readState(f.court.base.directory.resolve("laws_justice.dat"));h.assertTrue(restored.pendingReleases().containsKey(target.getUUID())&&restored.ledger().history().stream().anyMatch(d->d.action().equals("BAIL_RELEASE")),"Offline bail release was not durably queued and audited");f.court.base.actors.reconnect(target);pt.lawsjustice.service.JusticeService.login(target);h.assertTrue(!f.court.base.data.pendingReleases().containsKey(target.getUUID()),"The offline beneficiary was not released at login");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void preparedButUnappliedPaymentsNeverDebitAutomaticallyAtLogin(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var payer=f.court.accused;long before=f.balance(payer);UUID id=f.prepare(charge,payer);MoneySettlement.login(payer);h.assertTrue(f.balance(payer)==before&&f.finance().payments().get(id).status().equals("PREPARED"),"Login initiated an unauthorized fresh debit");MoneySettlement.cancel(payer,id);h.assertTrue(f.balance(payer)==before&&f.finance().payments().get(id).status().equals("CANCELLED"),"Unfunded intent could not be safely cancelled");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void savedReceiptFinishesAfterDisconnectWithoutDebitingAnOfflineWallet(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var payer=f.court.accused;long before=f.balance(payer);UUID id=f.prepare(charge,payer);var intent=f.finance().payments().get(id);h.assertTrue(PaymentReceipts.applyOnline(payer,intent),"Actual payer file failed to persist");f.court.base.actors.disconnect(payer);h.assertTrue(MoneySettlement.progress(payer.server,id,false),"Durable receipt could not settle offline");h.assertTrue(f.balance(payer)==before-intent.amount()&&f.finance().payments().get(id).status().equals("PAID"),"Offline completion changed the wallet twice");f.court.base.actors.reconnect(payer);}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void justiceSaveFailureAfterDurableDebitKeepsTheSameRetryReceipt(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var payer=f.court.accused;long before=f.balance(payer);UUID id=f.prepare(charge,payer);var intent=f.finance().payments().get(id);h.assertTrue(PaymentReceipts.applyOnline(payer,intent),"The actual wallet debit was not durable");var path=f.court.base.directory.resolve("laws_justice.dat");var blocker=f.court.base.directory.resolve("blocked-parent");Files.writeString(blocker,"not a directory");JusticeFixture.field(f.court.base.data,"file",blocker.resolve("laws_justice.dat"));h.assertTrue(!MoneySettlement.progress(payer.server,id,true)&&f.finance().payments().get(id).status().equals("PREPARED"),"An unpersisted finalization was reported as complete");JusticeFixture.field(f.court.base.data,"file",path);h.assertTrue(MoneySettlement.progress(payer.server,id,true)&&f.balance(payer)==before-intent.amount(),"Retry lost the debit receipt or charged twice");}catch(java.io.IOException e){throw new IllegalStateException(e);}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void aFailedPlayerSaveKeepsALiveReceiptSoRetryCannotDebitTwice(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var payer=f.court.accused;long before=f.balance(payer);UUID id=f.prepare(charge,payer);var intent=f.finance().payments().get(id);f.court.base.actors.disconnect(payer);h.assertTrue(!PaymentReceipts.applyOnline(payer,intent),"A disconnected player's unsaved debit was reported durable");h.assertTrue(PaymentReceipts.live(payer,intent)&&f.balance(payer)==before-intent.amount(),"Failed save did not retain its live single-debit receipt");JusticeFixture.rejected(h,()->MoneySettlement.cancel(payer,id));f.court.base.actors.reconnect(payer);h.assertTrue(PaymentReceipts.applyOnline(payer,intent)&&MoneySettlement.progress(payer.server,id,true)&&f.balance(payer)==before-intent.amount(),"A retry after player save failure debited again");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void receiptsSurviveActualVanillaDeathCloneAndRemainDurable(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var payer=f.court.accused;UUID id=MoneySettlement.pay(payer,charge);var receipt=f.finance().payments().get(id);h.assertTrue(receipt.status().equals("PAID"),"Initial payment failed");var replacement=f.court.base.actors.respawn(payer);replacement.restoreFrom(payer,false);h.assertTrue(PaymentReceipts.live(replacement,receipt),"Vanilla death clone lost the persisted payment marker");h.assertTrue(PaymentReceipts.durable(replacement.server,receipt),"Existing authoritative saved receipt vanished after death");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void malformedPersistedReceiptsFailClosedWithoutAnotherDebit(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var payer=f.court.accused;UUID id=f.prepare(charge,payer);var payment=f.finance().payments().get(id);var kept=new CompoundTag();kept.putString("lawsjustice_payments","forged receipt");payer.getPersistentData().put(Player.PERSISTED_NBT_TAG,kept);long before=f.balance(payer);h.assertTrue(!MoneySettlement.progress(payer.server,id,true)&&f.balance(payer)==before&&f.finance().payments().get(id).status().equals("PREPARED"),"Malformed receipt authorized another debit");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void formerPresidentCannotChangeBailOrReleaseThroughAnOldSession(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.bail();f.open(f.court.president);if(f.court.council!=null)f.court.council.mandate(f.court.stranger.getUUID(),System.currentTimeMillis()-1000,System.currentTimeMillis()+60000,System.currentTimeMillis()-500);var req=f.mutation(f.court.president);req.addProperty("charge",charge.toString());req.addProperty("reason","An expired official tried to revoke bail");f.act(f.court.president,"finance_revoke",req);h.assertTrue(f.finance().charges().get(charge).status().equals("DUE"),"Former President retained judicial power");req=f.mutation(f.court.president);req.addProperty("sentence",f.court.base.sentence().id().toString());req.addProperty("reason","Unauthorized release");f.act(f.court.president,"finance_release",req);h.assertTrue(f.court.base.sentence()!=null,"An unauthorized player released a prisoner");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void presidentCanAuthorizeReleaseWithoutAlteringWorkCredit(GameTestHelper h){try(var f=new FinanceFixture(h)){f.bail();var sentence=f.court.base.sentence();f.open(f.court.judge);var req=f.mutation(f.court.judge);req.addProperty("sentence",sentence.id().toString());req.addProperty("reason","A lawful pardon by the current authority");f.act(f.court.judge,"finance_release",req);h.assertTrue(f.court.base.sentence()==null&&f.finance().charges().values().iterator().next().status().equals("EXPIRED")&&f.court.base.data.work().credits().isEmpty()&&f.court.base.data.ledger().history().stream().anyMatch(d->d.action().equals("JUDICIAL_RELEASE")),"Judicial release changed work progress or left bail due");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void publicRegisterPublishesOnlyFinalDecisionsAndCannotAuthorizePayments(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();UUID extra=UUID.randomUUID();var caseFile=f.court.court().cases().values().iterator().next();var open=new pt.lawsjustice.domain.CourtLedger.CaseFile(extra,f.court.complainant.getUUID(),"Complainant",f.court.accused.getUUID(),"Accused","PRIVATE UNRESOLVED ALLEGATION",java.util.List.of(),"OPEN",System.currentTimeMillis(),0,"","","","",0,"");f.court.base.data.replaceCourt(f.court.court().file(open));var book=f.court.desk.offset(1,0,0);h.getLevel().setBlockAndUpdate(book,pt.lawsjustice.block.BlockRegistry.REGISTER_BOOK.get().defaultBlockState());f.court.stranger.setPos(book.getX()+.5,book.getY(),book.getZ()-1.5);FinanceService.open(f.court.stranger,book);var view=f.view(f.court.stranger);h.assertTrue(view.get("book").getAsBoolean()&&view.getAsJsonArray("records").size()==1&&!view.toString().contains("PRIVATE UNRESOLVED ALLEGATION")&&!view.toString().contains("PRIVATE JUSTICE"),"Public book leaked unresolved/private evidence or profile fields");var req=f.mutation(f.court.stranger);req.addProperty("charge",charge.toString());f.act(f.court.stranger,"finance_pay",req);h.assertTrue(f.finance().payments().isEmpty(),"Read-only record book became a remote payment session");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void closedOrRemoteFinanceSessionsCannotDebitThePlayer(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var payer=f.court.accused;f.open(payer);var req=f.mutation(payer);req.addProperty("charge",charge.toString());payer.setPos(f.court.desk.getX()+100,f.court.desk.getY(),f.court.desk.getZ());f.act(payer,"finance_pay",req);h.assertTrue(f.finance().payments().isEmpty(),"Remote packet authorized payment");f.open(payer);req=f.mutation(payer);req.addProperty("charge",charge.toString());FinanceService.closeSession(payer);f.act(payer,"finance_pay",req);h.assertTrue(f.finance().payments().isEmpty(),"Closed session authorized payment");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void previousFormatThreeMigratesCustodyCourtAndWorkWithoutInventingPayments(GameTestHelper h){try(var f=new FinanceFixture(h)){f.court.base.convict(36000);UUID id=f.court.file();f.court.hear(id);var file=f.court.base.directory.resolve("laws_justice.dat");var nbt=NbtIo.readCompressed(file,NbtAccounter.create(16000000));var json=com.google.gson.JsonParser.parseString(new String(nbt.getByteArray("ledger"),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();json.remove("finance");for(var row:json.getAsJsonObject("court").getAsJsonObject("cases").entrySet())row.getValue().getAsJsonObject().remove("originalTicks");nbt.putInt("format",3);nbt.putByteArray("ledger",json.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));NbtIo.writeCompressed(nbt,file);var restored=JusticeData.readState(file);h.assertTrue(restored.ledger().active().equals(f.court.base.data.ledger().active())&&restored.court().state().equals(f.court.court().state())&&restored.work().state().equals(f.court.base.data.work().state())&&restored.finance().charges().isEmpty(),"Format-three migration changed prior court/custody/work");restored.replaceFinance(restored.finance());h.assertTrue(NbtIo.readCompressed(file,NbtAccounter.create(16000000)).getInt("format")==4,"Finance migration was not saved as version four");}catch(java.io.IOException e){throw new IllegalStateException(e);}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void retryingUnfundedBailAfterReleaseCannotStartAFreshDebit(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.bail();var payer=f.court.stranger;long before=f.balance(payer);UUID id=f.prepare(charge,payer);var next=f.court.base.data.ledger().judicialRelease(f.court.accused.getUUID(),f.court.judge.getUUID(),"Current native judge","Pardoned before bail payment",System.currentTimeMillis(),false);f.court.base.data.replace(next);MoneySettlement.pay(payer,charge);h.assertTrue(f.balance(payer)==before&&f.finance().payments().get(id).status().equals("CANCELLED")&&f.finance().charges().get(charge).status().equals("EXPIRED"),"An expired unpaid bail attempt debited a friend after the sentence had ended");}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void oldConvictionDurationMigratesAndSurvivesCustodyHistoryRollover(GameTestHelper h){try(var f=new FinanceFixture(h)){
  f.court.base.register();UUID id=f.court.file();f.court.hear(id);var req=f.court.verdict(id);req.addProperty("prison",f.court.base.prisonId.toString());req.addProperty("cell",f.court.base.cellId.toString());req.addProperty("minutes",3);f.court.act(f.court.judge,"court_convict",req);var file=f.court.base.directory.resolve("laws_justice.dat");
  var nbt=NbtIo.readCompressed(file,NbtAccounter.create(16000000));var json=com.google.gson.JsonParser.parseString(new String(nbt.getByteArray("ledger"),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();json.remove("finance");for(var entry:json.getAsJsonObject("court").getAsJsonObject("cases").entrySet())entry.getValue().getAsJsonObject().remove("originalTicks");nbt.putInt("format",3);nbt.putByteArray("ledger",json.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));NbtIo.writeCompressed(nbt,file);
  var restored=JusticeData.readState(file);h.assertTrue(restored.court().cases().get(id).originalTicks()==3600,"Legacy conviction lost its authentic custody duration during migration");restored.replace(pt.lawsjustice.domain.JusticeLedger.restore(restored.ledger().prisons(),java.util.Map.of(),java.util.List.of()));restored.flush();var reopened=JusticeData.readState(file);h.assertTrue(reopened.court().cases().get(id).originalTicks()==3600&&reopened.ledger().history().isEmpty(),"Criminal sentence duration disappeared with the bounded custody history");
 }catch(java.io.IOException e){throw new IllegalStateException(e);}h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void actualHeldIdentityAuthenticatesAndForgedOrRemoteDocumentsFailClosed(GameTestHelper h){try(var f=new FinanceFixture(h)){
  var judge=f.court.judge;var accused=f.court.accused;
  if(!pt.lawsjustice.compat.JusticeIdentity.loaded()){JusticeFixture.rejected(h,()->pt.lawsjustice.compat.JusticeIdentity.inspect(judge,accused));}
  else try{
   var dataType=Class.forName("pt.realmidentity.data.IdentityData");Object data=dataType.getMethod("get",net.minecraft.server.MinecraftServer.class).invoke(null,judge.server);var ledgerField=dataType.getField("ledger");Object original=ledgerField.get(data);boolean dirty=(boolean)dataType.getMethod("isDirty").invoke(data);
   try{accused.getInventory().clearContent();accused.getInventory().setItem(1,new ItemStack(Items.PAPER,2));accused.getInventory().setItem(2,new ItemStack(Items.INK_SAC,2));
    Object deferred=Class.forName("pt.realmidentity.block.BlockRegistry").getField("WRITING_DESK").get(null);var block=(net.minecraft.world.level.block.Block)((java.util.function.Supplier<?>)deferred).get();var pos=f.court.desk.offset(2,0,0);h.getLevel().setBlockAndUpdate(pos,block.defaultBlockState());accused.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+1.5);h.getLevel().getBlockState(pos).useWithoutItem(h.getLevel(),accused,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos),net.minecraft.core.Direction.SOUTH,pos,false));
    ItemStack document=(ItemStack)Class.forName("pt.realmidentity.service.IdentityService").getMethod("trustedIssue",net.minecraft.server.level.ServerPlayer.class).invoke(null,accused);accused.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,document);judge.setPos(pos.getX()+1.5,pos.getY(),pos.getZ()+1.5);
    pt.lawsjustice.compat.JusticeIdentity.inspect(judge,accused);h.assertTrue(judge.chat.stream().anyMatch(c->c.getContents()instanceof net.minecraft.network.chat.contents.TranslatableContents t&&t.getKey().equals("lawsjustice.message.identity_document")),"Genuine held document was not shown through the installed Identity service");
    var forged=document.copy();var tag=forged.get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag();tag.getCompound("realmidentity").putUUID("documentId",UUID.randomUUID());forged.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(tag));accused.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,forged);JusticeFixture.rejected(h,()->pt.lawsjustice.compat.JusticeIdentity.inspect(judge,accused));
    accused.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,document);accused.setPos(pos.getX()+20,pos.getY(),pos.getZ());JusticeFixture.rejected(h,()->pt.lawsjustice.compat.JusticeIdentity.inspect(judge,accused));System.out.println("JUSTICE_IDENTITY_PHYSICAL_PASSED");
   }finally{ledgerField.set(data,original);dataType.getMethod("setDirty",boolean.class).invoke(data,dirty);}
  }catch(ReflectiveOperationException e){throw new IllegalStateException(e);}
 }h.succeed();}
 @GameTest(template="justice_empty",timeoutTicks=200) public static void installedCrownReceivesOnlyFundedMoneyAndDeduplicatesTheSameReceipt(GameTestHelper h){try(var f=new FinanceFixture(h)){UUID charge=f.fine();var p=f.court.accused;UUID id=MoneySettlement.pay(p,charge);var paid=f.finance().payments().get(id);h.assertTrue(paid.status().equals("PAID"),"Payer debit was not confirmed");if(JusticeTreasury.loaded()){try{var dataType=Class.forName("pt.crownledger.data.TreasuryData");Object data=dataType.getMethod("get",net.minecraft.server.MinecraftServer.class).invoke(null,p.server);var treasury=dataType.getField("treasury").get(data);Class<?> currency=Class.forName("pt.crownledger.domain.Treasury$Currency");@SuppressWarnings({"rawtypes","unchecked"})Object unit=Enum.valueOf((Class)currency,paid.currency());var balance=treasury.getClass().getMethod("balance",currency);long before=(long)balance.invoke(treasury,unit);JusticeTreasury.credit(p.server,paid);treasury=dataType.getField("treasury").get(data);long after=(long)balance.invoke(treasury,unit);h.assertTrue(after==before+paid.amount(),"Actual Crown treasury did not receive the backed payment");JusticeTreasury.credit(p.server,paid);treasury=dataType.getField("treasury").get(data);h.assertTrue((long)balance.invoke(treasury,unit)==after,"Duplicate justice transfer created money in Crown Ledger");f.court.base.data.replaceFinance(f.finance().transferred(id,System.currentTimeMillis()));h.assertTrue(f.finance().escrow(paid.currency())==0,"Transferred payment remained spendable in the court coffer");System.out.println("JUSTICE_CROWN_INCOME_PASSED");}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}else h.assertTrue(f.finance().escrow(paid.currency())==paid.amount(),"Standalone payments were lost without a public treasury");}h.succeed();}
}
